{
  "justification": "Unprompted salience concentrates on bread-and-butter economics (economy, unemployment, inflation) and on order/security (crime, immigration, defence). Care and fairness appear via NHS, education and inequality, while moral/purity themes (morality, drugs, environment) are present but secondary; with no directional data, weights reflect attention, not stance.",
  "foundations": [
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment; Inflation/Prices; Taxation; Low pay/Minimum wage; Petrol prices/Fuel; Pound/Exchange rate; Privatisation/Nationalisation; Education (human capital)",
      "weight": 0.30
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Morality/Individual behaviour",
      "weight": 0.22
    },
    {
      "foundation": "loyalty",
      "basis": "Race relations/Immigration/Immigrants; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe",
      "weight": 0.18
    },
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Education/Schools; Pensions/Social security; Housing",
      "weight": 0.16
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Public services in general; Housing; NHS/Education as equal access",
      "weight": 0.08
    },
    {
      "foundation": "sanctity",
      "basis": "Morality/Individual behaviour; Drug abuse; Pollution/Environment",
      "weight": 0.06
    }
  ]
}
